// Parses an absolute http(s) URL without the `URL` global, which n8n's Code
// node sandbox does not provide. Returns null for anything it will not vouch
// for, so every caller can treat null as "refuse this value".
function parseHttpUrl(value) {
  const raw = (value === null || value === undefined ? '' : String(value)).trim();
  if (!raw) return null;

  // No spaces, tabs, newlines or control characters anywhere. A URL carrying
  // one is either malformed or an attempt to hide a second value inside the
  // first, and neither is worth guessing about.
  for (let i = 0; i < raw.length; i++) {
    const code = raw.charCodeAt(i);
    if (code <= 0x20 || code === 0x7f) return null;
  }

  // Backslashes are rejected rather than normalised. Browsers treat a
  // backslash as "/", so an authority written with one can read as a hostile
  // host in a browser and a trusted host in a naive parser. Scout refuses the
  // ambiguity instead of picking a side.
  if (raw.indexOf('\\') !== -1) return null;

  const parts = /^([A-Za-z][A-Za-z0-9+.-]*):\/\/([^/?#]*)([^?#]*)(\?[^#]*)?(#[\s\S]*)?$/.exec(raw);
  if (!parts) return null;

  const protocol = parts[1].toLowerCase() + ':';
  if (protocol !== 'http:' && protocol !== 'https:') return null;

  const authority = parts[2];
  if (!authority) return null;

  // Split user information off the authority. Scout never sends credentials in
  // a URL, but workflow 01 has to be able to see that someone tried.
  let username = '';
  let password = '';
  let hostport = authority;
  const at = authority.lastIndexOf('@');
  if (at !== -1) {
    const userinfo = authority.slice(0, at);
    if (!userinfo) return null;
    hostport = authority.slice(at + 1);
    const sep = userinfo.indexOf(':');
    username = sep === -1 ? userinfo : userinfo.slice(0, sep);
    password = sep === -1 ? '' : userinfo.slice(sep + 1);
  }
  if (!hostport) return null;

  // Separate an optional port so it can never be mistaken for part of the host.
  let hostname = hostport;
  let port = '';
  if (hostport.charAt(0) === '[') {
    const close = hostport.indexOf(']');
    if (close === -1) return null;
    hostname = hostport.slice(0, close + 1);
    const rest = hostport.slice(close + 1);
    if (rest) {
      if (rest.charAt(0) !== ':') return null;
      port = rest.slice(1);
    }
  } else {
    const sep = hostport.indexOf(':');
    if (sep !== -1) {
      hostname = hostport.slice(0, sep);
      port = hostport.slice(sep + 1);
    }
    // Only ASCII hosts are accepted. An internationalised name would need
    // punycode conversion to compare safely, and Scout has no need of one.
    if (!/^[A-Za-z0-9._~%-]+$/.test(hostname)) return null;
  }
  if (!hostname) return null;
  if (port && !/^[0-9]+$/.test(port)) return null;

  const pathname = parts[3] || '/';
  const search = parts[4] || '';
  const hash = parts[5] || '';
  const host = port ? hostname + ':' + port : hostname;
  const href = protocol + '//' + host + pathname + search + hash;

  return {
    protocol: protocol,
    username: username,
    password: password,
    hostname: hostname,
    port: port,
    host: host,
    pathname: pathname,
    search: search,
    hash: hash,
    href: href,
    toString: function () { return href; }
  };
}

// VALIDATE SCOUT SETUP
// Stops the run before any HubSpot, Anthropic or Notion request when the
// configuration is missing or out of range. Each message names the exact
// Scout Setup field to fix.
const cfg = $('Scout Setup').first().json;
const problems = [];

const databaseId = (cfg.notionDatabaseId || '').toString().trim();
if (!databaseId) {
  problems.push('notionDatabaseId is empty. Paste the id of your Notion signal map database.');
}

// Every feed entry is a URL this workflow will actually fetch, so each one is
// checked here rather than trusted. Scout reads HubSpot's own public community
// RSS and nothing else: a typo, a redirect target or a lookalike host is a
// configuration error, not something to follow. One bad entry fails the run.
const FEED_HOST = 'community.hubspot.com';
const feeds = Array.isArray(cfg.hubspotCommunityFeeds)
  ? cfg.hubspotCommunityFeeds.map((f) => (f || '').toString().trim()).filter((f) => f.length > 0)
  : [];
if (feeds.length === 0) {
  problems.push('hubspotCommunityFeeds is empty. Add at least one HubSpot Community RSS URL.');
}

for (let i = 0; i < feeds.length; i++) {
  const label = 'hubspotCommunityFeeds[' + i + ']';
  const parsed = parseHttpUrl(feeds[i]);

  if (!parsed) {
    problems.push(label + ' is not an absolute URL.');
  } else if (parsed.protocol !== 'https:') {
    problems.push(label + ' must use https.');
  } else if (parsed.username || parsed.password) {
    problems.push(label + ' must not embed a username or password.');
  } else if (parsed.hostname.toLowerCase() !== FEED_HOST) {
    // Exact hostname match. A subdomain or a suffixed lookalike is not HubSpot.
    problems.push(label + ' must be hosted on ' + FEED_HOST + '.');
  } else if (!parsed.pathname.toLowerCase().endsWith('.rss')) {
    problems.push(label + ' must point at a .rss path.');
  }
}

const model = (cfg.anthropicModel || '').toString().trim();
if (!model) {
  problems.push('anthropicModel is empty. Set the Anthropic model id to classify with.');
}

const maxPostsPerFeed = Number(cfg.maxPostsPerFeed);
if (!Number.isInteger(maxPostsPerFeed) || maxPostsPerFeed < 1 || maxPostsPerFeed > 100) {
  problems.push('maxPostsPerFeed must be a whole number from 1 to 100.');
}

const lookbackHours = Number(cfg.lookbackHours);
if (!Number.isInteger(lookbackHours) || lookbackHours < 1 || lookbackHours > 168) {
  problems.push('lookbackHours must be a whole number from 1 to 168.');
}

if (problems.length > 0) {
  throw new Error('Scout Setup is not configured correctly. ' + problems.join(' '));
}

return [{ json: { validated: true, feedCount: feeds.length } }];

// FEED URLS
// These are public RSS feeds exposed by HubSpot Community. Feed paths can
// change, so verify them before activation.
// Add, remove or replace URLs in Scout Setup -> hubspotCommunityFeeds.
// Scout reads each feed once per scheduled run, without logging in.
const cfg = $('Scout Setup').first().json;

const feeds = (Array.isArray(cfg.hubspotCommunityFeeds) ? cfg.hubspotCommunityFeeds : [])
  .map((feedUrl) => (feedUrl || '').toString().trim())
  .filter((feedUrl) => feedUrl.length > 0);

return feeds.map((feedUrl) => ({ json: { feedUrl } }));

// EXTRACT POSTS + KEYWORD PRE-FILTER
// Flattens each feed's <item> list into individual posts, strips HTML, drops
// anything older than lookbackHours, keeps only posts that mention a RevOps
// keyword, then caps how many survive per feed. This is a cheap first pass so
// the model only sees plausible candidates.
const cfg = $('Scout Setup').first().json;
const lookbackMs = Number(cfg.lookbackHours) * 60 * 60 * 1000;
const maxPerFeed = Number(cfg.maxPostsPerFeed);
const nowMs = +$now;

const KEYWORDS = [
  'lifecycle', 'routing', 'route ', 'duplicate', 'dedup', 'enrich',
  'data quality', 'data-quality', 'lead scoring', 'lead score',
  'handoff', 'hand-off', 'hand off', 'sync', 'reporting', 'attribution',
  'property', 'properties', 'clean up', 'cleanup', 'migrat', 'workflow',
  'automation', 'deal stage', 'association', 'import', 'mapping'
];

const results = [];

for (const entry of $input.all()) {
  const d = entry.json || {};
  const channel = (d.rss && d.rss.channel) ? d.rss.channel : (d.channel || {});
  const board = (channel.title || 'HubSpot Community').toString().trim();

  let items = channel.item || [];
  if (!Array.isArray(items)) items = [items];

  const kept = [];

  for (const it of items) {
    if (!it) continue;
    if (kept.length >= maxPerFeed) break;

    const title = (it.title || '').toString();
    const link = (it.link || '').toString();
    const author = (it['dc:creator'] || it.creator || it.author || '').toString();
    const descRaw = (it.description || it['content:encoded'] || '').toString();
    const desc = descRaw
      .replace(/<[^>]*>/g, ' ')
      .replace(/&[a-z]+;/gi, ' ')
      .replace(/\s+/g, ' ')
      .trim();

    // Posts with no parseable date are kept rather than dropped. Silently
    // discarding them would hide every post if a feed changed its date
    // format. Dedupe Across Runs still stops repeat processing.
    const published = Date.parse((it.pubDate || it.published || '').toString());
    if (Number.isFinite(published) && (nowMs - published) > lookbackMs) continue;

    const haystack = (title + ' ' + desc).toLowerCase();
    if (!KEYWORDS.some((k) => haystack.includes(k))) continue;

    kept.push({ json: {
      board,
      postTitle: title,
      postUrl: link,
      postAuthor: author,
      postSnippet: desc.slice(0, 1200)
    }});
  }

  results.push(...kept);
}

return results;

// BUILD CLAUDE REQUEST
// Constructs one Anthropic Messages API body per post. The model id comes from
// Scout Setup so you can trade cost against depth without editing code.
const cfg = $('Scout Setup').first().json;
const model = (cfg.anthropicModel || '').toString().trim();

const SYSTEM = [
  'You qualify HubSpot Community forum posts as RevOps sales signals for a HubSpot data',
  'and automation consultancy. That consultancy fixes lead routing, lifecycle stage drift,',
  'duplicate records, enrichment gaps, data quality, and reporting trust.',
  'Decide whether the poster is an operator (RevOps, Marketing Ops, Sales Ops, HubSpot',
  'admin, or founder) describing one of those pains in a HubSpot context.',
  'Return ONLY valid minified JSON (no markdown, no code fences) with exactly these keys:',
  'relevant (boolean),',
  'warmth_tier (one of "Tier 1 (hot)","Tier 2 (warm)","Tier 3 (cool)","Tier 4 (cold)"),',
  'pain_areas (array, subset of ["Routing","Lifecycle","Dedupe","Enrichment","Data quality","Reporting"]),',
  'best_angle (one short diagnostic question under 200 characters),',
  'draft_comment (a 2 to 3 sentence helpful diagnostic comment, no pitch, no links),',
  'persona_type (one of "ICP buyer","ICP practitioner","Partner / consultant","Peer / networker","Unknown")',
  '- infer ONLY from role or title cues in the post; use "Unknown" if no role is evident,',
  'track (one of "Sales (ICP)","Connector","Unknown")',
  '- "Sales (ICP)" only if they read like a buyer or decision maker, "Connector" for consultants,',
  'agencies and peers worth knowing, otherwise "Unknown".',
  'If the post is a basic how-to question, unrelated, or not a HubSpot ops pain, set relevant to false.'
].join(' ');

return $input.all().map((entry) => {
  const p = entry.json;
  const userContent =
    'BOARD: ' + p.board + '\n' +
    'TITLE: ' + p.postTitle + '\n' +
    'AUTHOR: ' + p.postAuthor + '\n' +
    'BODY: ' + p.postSnippet;

  return { json: { ...p, _anthropicBody: {
    model: model,
    max_tokens: 500,
    system: SYSTEM,
    messages: [{ role: 'user', content: userContent }]
  }}};
});

// PARSE CLAUDE RESULT + BUILD NOTION PAGE BODY
// Relevant posts become signal rows. Irrelevant posts are dropped. Malformed
// model output becomes a "Needs review" row so nothing disappears silently.
const cfg = $('Scout Setup').first().json;
const DATABASE_ID = (cfg.notionDatabaseId || '').toString().trim();
const MAX_TEXT = 1900;

const VALID_TIERS = ['Tier 1 (hot)', 'Tier 2 (warm)', 'Tier 3 (cool)', 'Tier 4 (cold)'];
const VALID_PAIN_AREAS = ['Routing', 'Lifecycle', 'Dedupe', 'Enrichment', 'Data quality', 'Reporting'];
const VALID_PERSONAS = ['ICP buyer', 'ICP practitioner', 'Partner / consultant', 'Peer / networker', 'Unknown'];
const VALID_TRACKS = ['Sales (ICP)', 'Connector', 'Unknown'];

const cap = (value) => (value === null || value === undefined ? '' : value.toString().slice(0, MAX_TEXT));

const sources = $('Build Claude Request').all();
const inputs = $input.all();
const out = [];

for (let i = 0; i < inputs.length; i++) {
  const resp = inputs[i].json || {};
  const src = (sources[i] && sources[i].json) || {};

  let text = '';
  try {
    text = (resp.content || []).map((c) => c.text || '').join('');
  } catch (e) {
    text = '';
  }

  let verdict = null;
  let errorLabel = '';

  if (!text.trim()) {
    errorLabel = 'Model returned no text content';
  } else {
    try {
      verdict = JSON.parse(text);
    } catch (e) {
      const match = text.match(/\{[\s\S]*\}/);
      if (match) {
        try { verdict = JSON.parse(match[0]); } catch (_) { verdict = null; }
      }
      if (!verdict) errorLabel = 'Model response was not valid JSON';
    }
  }

  if (verdict && typeof verdict.relevant !== 'boolean') {
    verdict = null;
    errorLabel = 'Model response was missing the relevant flag';
  }

  // Malformed output is recorded for a human instead of being dropped. Only
  // the source title, source URL and a short error label are stored. The raw
  // model response is deliberately never written to Notion.
  if (!verdict) {
    const reviewName = cap(src.postTitle || 'Untitled community post');
    out.push({ json: {
      needsReview: true,
      recordName: reviewName,
      postUrl: src.postUrl || '',
      errorLabel: errorLabel,
      _notionBody: {
        parent: { database_id: DATABASE_ID },
        properties: {
          'Name': { title: [{ text: { content: reviewName } }] },
          'Signal': { rich_text: [{ text: { content: cap('Automatic classification failed. Review this post manually.') } }] },
          'Evidence': { rich_text: [{ text: { content: cap('Board: ' + (src.board || 'HubSpot Community') + ' - ' + errorLabel) } }] },
          'Warmth tier': { select: { name: 'Tier 4 (cold)' } },
          'Pain area': { multi_select: [] },
          'Best angle': { rich_text: [{ text: { content: '' } }] },
          'Draft': { rich_text: [{ text: { content: '' } }] },
          'Persona type': { select: { name: 'Unknown' } },
          'Track': { select: { name: 'Unknown' } },
          'Source': { select: { name: 'HubSpot Community' } },
          'Source URL': { url: src.postUrl || null },
          'Next action': { select: { name: 'Monitor' } },
          'Status': { select: { name: 'Needs review' } },
          'Replied': { checkbox: false }
        }
      }
    }});
    continue;
  }

  if (verdict.relevant !== true) continue;

  const warmth = VALID_TIERS.includes(verdict.warmth_tier) ? verdict.warmth_tier : 'Tier 3 (cool)';
  const painAreas = Array.isArray(verdict.pain_areas)
    ? verdict.pain_areas.filter((b) => VALID_PAIN_AREAS.includes(b))
    : [];
  const bestAngle = cap(verdict.best_angle);
  const draft = cap(verdict.draft_comment);
  const persona = VALID_PERSONAS.includes(verdict.persona_type) ? verdict.persona_type : 'Unknown';
  const track = VALID_TRACKS.includes(verdict.track) ? verdict.track : 'Unknown';
  const recordName = cap((src.postAuthor && src.postAuthor.trim()) || src.postTitle || 'Unknown poster');

  out.push({ json: {
    recordName,
    warmth,
    painAreas,
    postUrl: src.postUrl,
    _notionBody: {
      parent: { database_id: DATABASE_ID },
      properties: {
        'Name': { title: [{ text: { content: recordName } }] },
        'Signal': { rich_text: [{ text: { content: cap(src.postTitle + ' - ' + src.postSnippet) } }] },
        'Evidence': { rich_text: [{ text: { content: cap('Board: ' + src.board) } }] },
        'Warmth tier': { select: { name: warmth } },
        'Pain area': { multi_select: painAreas.map((b) => ({ name: b })) },
        'Best angle': { rich_text: [{ text: { content: bestAngle } }] },
        'Draft': { rich_text: [{ text: { content: draft } }] },
        'Persona type': { select: { name: persona } },
        'Track': { select: { name: track } },
        'Source': { select: { name: 'HubSpot Community' } },
        'Source URL': { url: src.postUrl || null },
        'Next action': { select: { name: 'Comment' } },
        'Status': { select: { name: 'New' } },
        'Replied': { checkbox: false }
      }
    }
  }});
}

return out;
